  async function saveProfile(event){event.preventDefault();const f=new FormData(event.currentTarget);await act(async()=>{const {error}=await db.from('profiles').update({display_name:f.get('display_name').trim(),bio:f.get('bio').trim()}).eq('id',user.id);if(error)throw error;setProfile(p=>({...p,display_name:f.get('display_name').trim(),bio:f.get('bio').trim()}));setMessage('Profile saved.');setModal(null)})}
  async function exportAccount(){await act(async()=>{const {data,error}=await db.rpc('export_account');if(error)throw error;const levelResult=await db.rpc('voter_levels',{member_ids:[user.id]});if(levelResult.error)throw levelResult.error;const musicExport=await db.rpc('export_own_music');if(musicExport.error)throw musicExport.error;const photos=await db.from('profile_photos').select('*').eq('user_id',user.id);if(photos.error)throw photos.error;const json=JSON.stringify({...data,profile_photos:photos.data,music:musicExport.data,voter_level:levelResult.data?.[0]||null},null,2);setAccountExport({json,url:URL.createObjectURL(new Blob([json],{type:'application/json'}))});setMessage('Your export is ready. Save the file below, or copy the text if your browser blocks downloads.')})}
  async function deleteAccount(event){event.preventDefault();const confirmation=new FormData(event.currentTarget).get('confirmation');await act(async()=>{const cleanup=await db.rpc('prepare_photo_account_deletion',{confirmation});if(cleanup.error)throw cleanup.error;try{const paths=cleanup.data||[];for(let index=0;index<paths.length;index+=100){const removed=await db.storage.from('discovery-photos').remove(paths.slice(index,index+100));if(removed.error)throw removed.error;}const musicCleanup=await db.rpc('prepare_music_account_deletion',{confirmation});if(musicCleanup.error)throw musicCleanup.error;for(let i=0;i<(musicCleanup.data||[]).length;i+=100){const removed=await db.storage.from('discovery-music').remove(musicCleanup.data.slice(i,i+100));if(removed.error)throw removed.error;}const deleted=await db.rpc('delete_own_account',{confirmation});if(deleted.error)throw deleted.error;}catch(error){await db.rpc('cancel_photo_account_deletion');throw error;}await db.auth.signOut({scope:'local'});setUser(null);setProfile(null);setVotes({});setModal(null);reset();setView('Trending');setMessage('Your account and community data have been deleted.');await load()})}
