  {view==="My discoveries"&&deletedDiscoveries.length>0&&<details className="deleted-discoveries"><summary>Deleted discoveries ({deletedDiscoveries.length})</summary><p className="muted">Only you can restore these. Restored discoveries return to review.</p>{deletedDiscoveries.map(x=><div className="notice actions" key={x.id}><span>{x.title}</span><button disabled={busy} onClick={()=>restoreDiscovery(x.id)}>Restore discovery</button></div>)}</details>}
